begin;
do $$
declare owner_id uuid:=gen_random_uuid();client_id uuid:=gen_random_uuid();other_id uuid:=gen_random_uuid();tid uuid;other_tid uuid;pid uuid;mid uuid;pending_id uuid;pending_user uuid:=gen_random_uuid();d jsonb;p jsonb;r jsonb;denied boolean;mail text;new_mail text;fixture_slug text;
begin
 mail:='editor-client-'||substr(client_id::text,1,8)||'@example.invalid';new_mail:='editor-new-'||substr(client_id::text,1,8)||'@example.invalid';fixture_slug:='editor-fixture-'||substr(client_id::text,1,8);
 insert into auth.users(id,email,email_confirmed_at) values(owner_id,'editor-owner-fixture@example.invalid',now()),(client_id,mail,now()),(other_id,'editor-other-fixture@example.invalid',now());
 insert into public.platform_admins values(owner_id);
 insert into public.plans(name,amount,months) values('Editor fixture',99.90,1) returning id into pid;
 insert into public.tenants(name,slug,responsible,email) values('Editor fixture',fixture_slug,'Fixture',mail) returning id into tid;
 insert into public.tenants(name,slug,responsible,email) values('Other fixture',fixture_slug||'-other','Other','editor-other-fixture@example.invalid') returning id into other_tid;
 insert into public.licenses(tenant_id,plan_id,starts_on,expires_on,amount) values(tid,pid,current_date,current_date+30,99.90),(other_tid,pid,current_date,current_date+30,99.90);
 insert into public.settings(tenant_id) values(tid),(other_tid);
 insert into public.memberships(tenant_id,email,role) values(tid,mail,'admin') returning id into mid;
 perform set_config('request.jwt.claim.sub',other_id::text,true);
 denied:=false;begin perform public.agenda_master_company('get',jsonb_build_object('tenant_id',tid));exception when others then denied:=true;end;if not denied then raise exception 'FAIL ordinary account can manage companies';end if;
 perform set_config('request.jwt.claim.sub',owner_id::text,true);
 d:=public.agenda_master_company('get',jsonb_build_object('tenant_id',tid));
 if d->'members'->0->>'login_email'<>mail then raise exception 'FAIL legacy account discovery';end if;
 p:=d->'tenant'||d->'license'||jsonb_build_object('tenant_id',tid,'revision',d->>'revision','name','Empresa editada','responsible','Responsável editado','phone','24999999999','email','commercial-fixture@example.invalid','slug',fixture_slug||'-new','status','suspended','document_type','CPF','document_number','52998224725','amount',199.90,'paid',true,'starts_on',current_date,'expires_on',current_date+365);
 perform public.agenda_master_company('save',p);
 if not exists(select 1 from public.tenants where id=tid and name='Empresa editada' and responsible='Responsável editado' and email='commercial-fixture@example.invalid' and slug=fixture_slug||'-new' and status='suspended') then raise exception 'FAIL complete business data save';end if;
 if not exists(select 1 from public.licenses where tenant_id=tid and amount=199.90 and paid and expires_on=current_date+365) then raise exception 'FAIL license save';end if;
 if (select email from auth.users where id=client_id)<>mail then raise exception 'FAIL commercial email changed login';end if;
 denied:=false;begin perform public.agenda_master_company('save',p);exception when others then denied:=true;end;if not denied then raise exception 'FAIL stale company update';end if;
 d:=public.agenda_master_company('get',jsonb_build_object('tenant_id',tid));
 p:=jsonb_build_object('tenant_id',tid,'id',mid,'email',new_mail,'revision',d->'members'->0->>'revision');
 r:=public.agenda_master_company('credentials_prepare',p);
 if r->>'user_id'<>client_id::text or not exists(select 1 from public.memberships where id=mid and user_id=client_id) then raise exception 'FAIL legacy user binding before email update';end if;
 -- Simulate Auth's successful email change. No credential/hash is read or written.
 update auth.users set email=new_mail where id=client_id;
 perform public.agenda_master_company('credentials_finish',p||jsonb_build_object('revision',r->>'revision','account_id',client_id));
 if not exists(select 1 from public.memberships where id=mid and email=new_mail and user_id=client_id) then raise exception 'FAIL login email sync';end if;
 if (select email from public.tenants where id=tid)<>'commercial-fixture@example.invalid' then raise exception 'FAIL login edit changed commercial email';end if;
 insert into public.memberships(tenant_id,email,user_id,role) values(other_tid,new_mail,client_id,'admin');
 d:=public.agenda_master_company('get',jsonb_build_object('tenant_id',tid));
 denied:=false;begin perform public.agenda_master_company('credentials_prepare',jsonb_build_object('tenant_id',tid,'id',mid,'email',new_mail,'revision',d->'members'->0->>'revision'));exception when others then denied:=true;end;if not denied then raise exception 'FAIL shared credentials allowed';end if;
 perform public.agenda_master_company('member_save',jsonb_build_object('tenant_id',tid,'id',mid,'revision',d->'members'->0->>'revision','role','admin','active',false));
 if exists(select 1 from public.memberships where id=mid and active) or not exists(select 1 from public.memberships where tenant_id=other_tid and user_id=client_id and active) then raise exception 'FAIL tenant-scoped permission change';end if;
 perform public.agenda_master_company('member_save',jsonb_build_object('tenant_id',tid,'email','pending-editor-fixture@example.invalid','role','admin','active',true));
 select id into pending_id from public.memberships where tenant_id=tid and email='pending-editor-fixture@example.invalid';
 select md5(to_jsonb(m)::text) into mail from public.memberships m where id=pending_id;
 p:=jsonb_build_object('tenant_id',tid,'id',pending_id,'revision',mail,'email','pending-editor-fixture@example.invalid');
 r:=public.agenda_master_company('credentials_prepare',p);
 if r->>'user_id' is not null then raise exception 'FAIL pending access unexpectedly has account';end if;
 insert into auth.users(id,email,email_confirmed_at,raw_app_meta_data) values(pending_user,'pending-editor-fixture@example.invalid',now(),jsonb_build_object('agenda_member_actor',owner_id,'agenda_member_id',pending_id));
 perform public.agenda_master_company('credentials_finish',p||jsonb_build_object('account_id',pending_user));
 if not exists(select 1 from public.memberships where id=pending_id and user_id=pending_user) then raise exception 'FAIL pending account activation';end if;
 insert into public.memberships(tenant_id,email,user_id,role) values(tid,'editor-owner-fixture@example.invalid',owner_id,'admin') returning id into mid;
 select md5(to_jsonb(m)::text) into mail from public.memberships m where id=mid;
 denied:=false;begin perform public.agenda_master_company('credentials_prepare',jsonb_build_object('tenant_id',tid,'id',mid,'revision',mail,'email','editor-owner-fixture@example.invalid'));exception when others then denied:=true;end;if not denied then raise exception 'FAIL Master credential protection';end if;
 denied:=false;begin perform public.agenda_master_company('get',jsonb_build_object('tenant_id',tid,'new_password','never-store-passwords'));exception when others then denied:=true;end;if not denied then raise exception 'FAIL credential payload accepted';end if;
 perform set_config('request.jwt.claim.sub','',true);
 denied:=false;begin perform public.agenda_master_company('get',jsonb_build_object('tenant_id',tid));exception when others then denied:=true;end;if not denied then raise exception 'FAIL anonymous company details';end if;
 if has_function_privilege('anon','public.agenda_master_company(text,jsonb)','execute') then raise exception 'FAIL anonymous execute grant';end if;
end $$;
select 'PASS: Master-only complete editing, license changes, commercial/login email separation, stale edit rejection, legacy Auth binding, credential sync, shared/Master account protection, scoped permissions and pending-account activation' as result;
rollback;
